select a.id from b_xiecheng_colliding_data_rob a join ${tableName} c on a.cell_sha256_code_list = c.cell and c.is_delete = 0 left join ( ${queryRuleScoreDataSql} ) b on c.cell = b.cell and b.is_delete = 0 where a.is_delete = 0 and b.id is null and a.package_id = 120007
and a.id > #{minId}
order by a.id limit #{pageSize};

select a.id from b_xiecheng_colliding_data_black_list b
join b_xiecheng_colliding_data_rob a on a.cell_sha256_code_list = b.cell_sha256 and b.label_type = #{type}
and b.status = 1
where a.is_delete = 0

    and a.id > #{minId}

order by a.id limit #{pageSize};

